import{_ as t,c as n,o as s,j as a,a as e}from"./chunks/framework.mdxl8zx-.js";const b=JSON.parse('{"title":"初识Java","description":"","frontmatter":{},"headers":[],"relativePath":"backEnd/java/index.md","filePath":"backEnd/java/index.md"}'),o={name:"backEnd/java/index.md"},c=a("h1",{id:"初识java",tabindex:"-1"},[e("初识Java "),a("a",{class:"header-anchor",href:"#初识java","aria-label":'Permalink to "初识Java"'},"​")],-1),d=a("h2",{id:"简介",tabindex:"-1"},[e("简介 "),a("a",{class:"header-anchor",href:"#简介","aria-label":'Permalink to "简介"'},"​")],-1),i=a("p",null,"Java是一个面向对象的编程语言，由Sun Microsystems公司于1995年5月23日推出，Java最初被命名为Oak，目标应用是家用电器等家用电器，但由于市场反应不佳，Sun公司放弃了该计划。1996年1月，Sun正式将Java命名为Java，并正式推出Java 1.0。Java最初被设计为用于消费电子和家用电器等嵌入式系统，但后来Java逐渐成为企业级应用开发的首选语言。",-1),r=a("p",null,"Java是一种跨平台的编程语言，可以在不同的操作系统上运行，如Windows、Linux、Mac OS等。Java程序可以在任何安装了Java虚拟机（JVM）的设备上运行，这使得Java程序具有很好的可移植性。",-1),v=a("p",null,"Java是一种面向对象的编程语言，它将程序分解为对象，每个对象都有自己的属性和方法。Java程序由类和对象组成，类是对象的蓝图，对象是类的实例。Java程序可以创建多个对象，每个对象都有自己的属性和方法。Java程序可以通过继承、多态等特性来实现代码的重用和扩展。",-1),l=a("p",null,"Java是一种强类型的编程语言，它要求在编译时进行类型检查，以确保程序的正确性。Java程序由源代码文件组成，这些文件使用.java扩展名。Java编译器将源代码文件编译为字节码文件，这些文件使用.class扩展名。Java虚拟机（JVM）可以执行字节码文件，并将其转换为机器代码，以便在计算机上运行。",-1),J=[c,d,i,r,v,l];function _(h,p,u,m,x,f){return s(),n("div",null,J)}const j=t(o,[["render",_]]);export{b as __pageData,j as default};
